import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import type { Finding, GuardrailReport, Severity, ShapeDetected } from '../types.js'
import { rules as defaultRules, type Rule } from './rules/index.js'
import { detectShape } from './shape.js'
import { walkProject, type ProjectFile } from './walk.js'

export interface GuardrailMeta { id: string; title: string; shape: 'A' | 'B' | 'both'; detect: 'static' | 'manual' | 'contract'; severity: Severity; rule: string }

/** Reads `<contentDir>/guardrails.json` (generated by `pnpm sync`). */
export function loadGuardrailMeta(contentDir: string): GuardrailMeta[] {
  const raw = JSON.parse(readFileSync(join(contentDir, 'guardrails.json'), 'utf8')) as GuardrailMeta[]
  return raw.map(({ id, title, shape, detect, severity, rule }) => ({ id, title, shape, detect, severity, rule }))
}

// `// bsv-guardrail-ignore G-xx reason`, also in `#`, `<!--` and `/*` comment forms.
const IGNORE_RE = /(?:\/\/|#|<!--|\/\*)\s*bsv-guardrail-ignore\s+(G-\d\d)(?!\d)/g

/**
 * True when an ignore comment naming exactly `id` sits on `line` or the line above.
 * `line` is 1-based, the same numbering findings use.
 */
export function isSuppressed(file: ProjectFile, line: number, id: string): boolean {
  const lines = file.text.split('\n')
  return [line, line - 1].some(n => {
    const text = n >= 1 ? lines[n - 1] : undefined
    return text !== undefined && [...text.matchAll(IGNORE_RE)].some(m => m[1] === id)
  })
}

function firstSentence(text: string): string {
  return text.match(/^[\s\S]*?[.!?](?=\s|$)/)?.[0] ?? text
}

function shapeExcludes(ruleShape: GuardrailMeta['shape'], shape: ShapeDetected): boolean {
  return (ruleShape === 'A' && shape === 'B') || (ruleShape === 'B' && shape === 'A')
}

/**
 * Runs every guardrail against the project at `root`. Read-only: it never writes to `root`.
 * Per guardrail, in id order: shape mismatch → notApplicable; manual/contract detection,
 * or a static guardrail with no registered rule → manualChecklist; otherwise the rule runs and
 * lands in notApplicable (applicable false), findings (unsuppressed hits) or passed.
 * A rule that throws becomes a `warn` finding for its guardrail (file '', line 0) and the run continues.
 * `rules` overrides the registered rule set (tests use it; defaults to the exported `rules`).
 * `onSkip` hears about each file the walker could not read.
 */
export async function runGuardrails(
  root: string,
  opts: {
    shape?: 'A' | 'B' | 'auto'
    include?: string[]
    exclude?: string[]
    contentDir: string
    rules?: Rule[]
    onSkip?: (rel: string, reason: string) => void
  },
): Promise<GuardrailReport> {
  const metas = loadGuardrailMeta(opts.contentDir)
  const files = await walkProject(root, { include: opts.include, exclude: opts.exclude, onSkip: opts.onSkip })
  const shapeDetected = detectShape(files)
  const shape: ShapeDetected = opts.shape === 'A' || opts.shape === 'B' ? opts.shape : shapeDetected
  const byRel = new Map(files.map(f => [f.rel, f]))
  const ruleSet = opts.rules ?? defaultRules

  const report: GuardrailReport = { shapeDetected, findings: [], passed: [], notApplicable: [], manualChecklist: [] }
  for (const meta of metas) {
    if (shapeExcludes(meta.shape, shape)) { report.notApplicable.push(meta.id); continue }
    const rule = meta.detect === 'static' ? ruleSet.find(r => r.id === meta.id) : undefined
    if (!rule) { report.manualChecklist.push(meta.id); continue }

    let result: ReturnType<Rule['run']>
    try {
      result = rule.run({ files, shape, root, meta, contentDir: opts.contentDir })
    } catch (e) {
      const why = e instanceof Error ? e.message : String(e)
      report.findings.push({
        id: meta.id, severity: 'warn', file: '', line: 0, snippet: '',
        fix: `The ${meta.id} check failed to run (${why}); check this guardrail by hand.`,
        ref: `bsv://guardrails#${meta.id}`,
      })
      continue
    }
    if (!result.applicable) { report.notApplicable.push(meta.id); continue }
    const kept: Finding[] = result.findings
      .filter(f => { const file = byRel.get(f.file); return !(file && isSuppressed(file, f.line, meta.id)) })
      .map(f => ({ ...f, fix: firstSentence(meta.rule), ref: `bsv://guardrails#${meta.id}` }))
    if (kept.length) report.findings.push(...kept)
    else report.passed.push(meta.id)
  }
  return report
}
